let state=JSON.parse(localStorage.getItem('pb-active')||'null');if(state&&!state.type)state.type='x01';if(state?.type==='checkout'&&!state.limitType){state.limitType='rounds';state.maxRounds=Math.max(20,(state.results?.length||0)+1);delete state.attempts;delete state.targetAttempts;}
