function play(){let last=state.visits.slice(-3),round=state.visits.length+1;const auto=state.left>=2&&state.left<=60;const optional=state.left>=61&&state.left<=170;const flag=auto?`<div class='checkoutflag auto'>✓ ${t().autoCheckout}</div>`:optional?`<button class='checkoutflag ${state.checkoutIntent?'on':''}' data-a=checkoutIntent>${state.checkoutIntent?'✓ ':''}${t().attemptCheckout}</button>`:'';A.innerHTML=`<main class='app play-screen' data-game-surface><div class=top><div class=title>${state.game} ${state.out}</div><div class=roundinfo>${t().round} ${Math.min(round,state.maxRounds)} / ${state.maxRounds}</div></div><div class=score>${state.left}</div>${flag}<div class=visits>${[0,1,2].map((_,i)=>`<div class=visit>${last[i]?.score??''}</div>`).join('')}</div><div class=remaining>${t().remaining} ${state.left}</div><div class=error>${esc(err)}</div>${numericArea([100,60,57,58,26,95,140,180,0])}<button class='btn undobtn' data-a=undo ${state.canUndo?'':'disabled'}>${t().undo}</button><div class=gesturehint>••</div></main>`}
