function menuModal(){modal(`<h2>${t().menu}</h2><div class=menugrid><button class='btn red' data-a=closeMenu>${t().resumeMenu}</button><button class='btn' data-a=undoMenu ${state?.canUndo?'':'disabled'}>${t().undo}</button><button class='btn' data-a=restart>${t().restart}</button><button class='btn danger' data-a=end>${t().end}</button><button class='btn' data-a=home>${t().home}</button></div>`)}
function endConfirm(){modal(`<h2>${t().confirmEnd}</h2><div class=modalactions><button class='btn danger' data-a=confirmEnd>${t().yesEnd}</button><button class='btn' data-a=closeMenu>${t().no}</button></div>`)}
function calcX01(s,finished,finishDart=0){const visits=s.visits.slice();let darts=visits.length*3;if(finished&&finishDart)darts=(visits.length-1)*3+finishDart;const scored=s.game-(finished?0:s.left),first=visits.slice(0,3).reduce((a,v)=>a+(v.bust?0:v.score),0),firstDarts=Math.min(9,visits.length*3),attempts=visits.reduce((a,v)=>a+(v.checkoutAttempts||0),0)+(finished?1:0);return {game:s.game,out:s.out,finished,darts,left:s.left,avg:darts?scored/darts*3:0,ppd:darts?scored/darts:0,first9:firstDarts?first/firstDarts*3:0,checkoutAttempts:attempts,checkoutPct:attempts?(finished?100/attempts:0):0,highestCheckout:finished?(s.finishScore||0):0,c100:visits.filter(v=>v.score>=100).length,c140:visits.filter(v=>v.score>=140).length,c170:visits.filter(v=>v.score>=170).length,c180:visits.filter(v=>v.score===180).length,busts:visits.filter(v=>v.bust).length}}
function storeX01(r){const all=loadObj('pb-x01-stats'),k=`${r.game}-${r.out}`,x=all[k]||{games:0,completed:0,totalDarts:0,totalPoints:0,checkoutAttempts:0,checkoutHits:0,highestCheckout:0,bestAvg:0,c100:0,c140:0,c170:0,c180:0,busts:0};x.games++;if(r.finished)x.completed++;x.totalDarts+=r.darts;x.totalPoints+=r.finished?r.game:r.game-r.left;x.checkoutAttempts+=r.checkoutAttempts;x.checkoutHits+=r.finished?1:0;x.highestCheckout=Math.max(x.highestCheckout,r.highestCheckout);x.bestAvg=Math.max(x.bestAvg,r.avg);['c100','c140','c170','c180','busts'].forEach(k=>x[k]+=r[k]);all[k]=x;saveObj('pb-x01-stats',all);return x}
function resultModal(r,kind='x01'){if(kind==='high')return highResult(r);if(kind==='split')return splitResult(r);modal(`<h2>${r.finished?t().completed:t().failed}</h2><div class=resultscore>${r.game} ${r.out}</div><div class=statgrid><div><b>${r.avg.toFixed(1)}</b><small>${t().avg}</small></div><div><b>${r.first9.toFixed(1)}</b><small>${t().first9}</small></div><div><b>${r.ppd.toFixed(2)}</b><small>${t().ppd}</small></div><div><b>${r.darts}</b><small>${t().darts}</small></div><div><b>${r.checkoutPct.toFixed(0)}%</b><small>${t().checkoutPct}</small></div><div><b>${r.highestCheckout||'—'}</b><small>${t().highestCheckout}</small></div></div><div class=scoringline><span>100+ <b>${r.c100}</b></span><span>140+ <b>${r.c140}</b></span><span>170+ <b>${r.c170}</b></span><span>180 <b>${r.c180}</b></span></div><div class=modalactions><button class='btn red' data-a=playAgain data-game=${r.game} data-out=${r.out}>${t().playAgain}</button><button class='btn' data-a=home>${t().home}</button></div>`)}
function submitX01(sc){err='';if(sc<0||sc>180){err=t().scoreRange;return play()}const before=state.left,after=before-sc,checkoutVisit=(before>=2&&before<=60)||(before>=61&&before<=170&&state.checkoutIntent===true);state.canUndo=true;state.checkoutIntent=false;if(after<0||(state.out==='DO'&&after===1)){state.visits.push({score:sc,bust:true,before,left:before,checkoutVisit});input='';save();if(checkRoundLimit())return;if(checkoutVisit)attemptsModal();else play();return}if(after===0){state.pendingScore=sc;state.pendingBefore=before;state.pendingCheckoutVisit=checkoutVisit;save();input='';return finishModal()}state.left=after;state.visits.push({score:sc,before,left:after,checkoutVisit});input='';save();if(checkRoundLimit())return;if(checkoutVisit)attemptsModal();else play()}
function checkRoundLimit(){if(state.visits.length>=state.maxRounds){const snap=structuredClone(state),r=calcX01(snap,false);storeX01(r);state=null;save();route='home';home();resultModal(r);return true}return false}
function finishX01(d){document.querySelector('.modal')?.remove();const snap=structuredClone(state);snap.left=0;snap.finishScore=snap.pendingBefore;snap.visits.push({score:snap.pendingScore,before:snap.pendingBefore,left:0,finishDart:d,checkoutVisit:snap.pendingCheckoutVisit||false});const r=calcX01(snap,true,d);r.highestCheckout=snap.pendingBefore;storeX01(r);state=null;save();input='';route='home';home();resultModal(r)}
function submitHigh(sc){err='';if(sc<0||sc>180){err=t().scoreRange;return highPlay()}state.visits.push({score:sc});state.canUndo=true;input='';save();if(state.visits.length>=state.maxRounds)return finishHigh();highPlay()}
function finishHigh(){const s=structuredClone(state),total=s.visits.reduce((a,v)=>a+v.score,0),avg=total/s.maxRounds,best=Math.max(...s.visits.map(v=>v.score)),r={rounds:s.maxRounds,total,avg,best,c100:s.visits.filter(v=>v.score>=100).length,c140:s.visits.filter(v=>v.score>=140).length,c170:s.visits.filter(v=>v.score>=170).length,c180:s.visits.filter(v=>v.score===180).length};const all=loadObj('pb-high-stats'),k=String(s.maxRounds),x=all[k]||{games:0,total:0,best:0};x.games++;x.total+=total;x.best=Math.max(x.best,total);all[k]=x;saveObj('pb-high-stats',all);r.lifetime=x;state=null;save();route='home';home();highResult(r)}
function highResult(r){modal(`<h2>${t().completed}</h2><div class=resultscore>${r.total}</div><div class=statgrid><div><b>${r.avg.toFixed(1)}</b><small>${t().avg}</small></div><div><b>${r.best}</b><small>${t().bestVisit}</small></div><div><b>${r.lifetime.best}</b><small>${lang==='hr'?'OSOBNI REKORD':'PERSONAL BEST'}</small></div><div><b>${r.c100}</b><small>100+</small></div><div><b>${r.c140}</b><small>140+</small></div><div><b>${r.c180}</b><small>180</small></div></div><div class=modalactions><button class='btn red' data-a=playHighAgain data-rounds=${r.rounds}>${t().playAgain}</button><button class='btn' data-a=home>${t().home}</button></div>`)}
function submitSplit(value,bullHits=null){const target=splitTargets()[state.visits.length],before=state.score;let points=0,halved=false;if(target==='D'||target==='T'){points=+value;if(points<0||points>180){err=t().scoreRange;return splitPlay()}}else if(target==='B'){points=+value}else{const marks=+value;if(marks<0||marks>9)return;points=marks*target}if(points===0){state.score=Math.ceil(state.score/2);halved=true}else state.score+=points;state.visits.push({target,points,before,after:state.score,halved,bullHits:target==='B'?bullHits:null});state.canUndo=true;input='';err='';save();if(state.visits.length>=9)return finishSplit();splitPlay()}
function finishSplit(){if(!state||state.type!=='split')return;const s=structuredClone(state),r={score:s.score,direction:s.direction,halves:s.visits.filter(v=>v.halved).length,successful:s.visits.filter(v=>!v.halved).length,visits:s.visits};const all=loadObj('pb-split-stats'),x=all.combined||{games:0,total:0,best:null,halves:0,target:{}};x.games++;x.total+=r.score;x.best=x.best===null?r.score:Math.max(x.best,r.score);x.halves+=r.halves;for(const v of r.visits){const k=String(v.target);x.target[k]=x.target[k]||{rounds:0,success:0,points:0,hits:0};x.target[k].rounds++;if(!v.halved)x.target[k].success++;x.target[k].points+=v.points;if(v.target==='B'&&v.bullHits!=null)x.target[k].hits=(x.target[k].hits||0)+v.bullHits}all.combined=x;saveObj('pb-split-stats',all);r.lifetime=x;state=null;save();route='home';home();splitResult(r)}
function splitResult(r){modal(`<h2>${t().completed}</h2><div class=resultscore>${r.score}</div><div class=statgrid><div><b>${r.halves}</b><small>${t().halves}</small></div><div><b>${Math.round(r.successful/9*100)}%</b><small>${lang==='hr'?'USPJEŠNE RUNDE':'SUCCESSFUL ROUNDS'}</small></div><div><b>${r.lifetime.best}</b><small>${lang==='hr'?'OSOBNI REKORD':'PERSONAL BEST'}</small></div><div><b>${(r.lifetime.total/r.lifetime.games).toFixed(0)}</b><small>${lang==='hr'?'PROSJEČNI SCORE':'AVERAGE SCORE'}</small></div></div><div class=modalactions><button class='btn red' data-a=playSplitAgain data-dir=${r.direction}>${t().playAgain}</button><button class='btn' data-a=home>${t().home}</button></div>`)}
function undo(){if(!state||!state.canUndo)return;if(state.type==='x01'){if(state.pendingScore!==undefined){delete state.pendingScore;delete state.pendingBefore;delete state.pendingCheckoutVisit;state.canUndo=false;save();document.querySelector('.modal')?.remove();return play()}const v=state.visits.pop();if(v)state.left=v.before}else if(state.type==='high'){state.visits.pop()}else if(state.type==='split'){const v=state.visits.pop();if(v)state.score=v.before}else if(state.type==='rtw'){state.visits.pop()}else if(state.type==='bobs'){const v=state.visits.pop();if(v)state.score=v.before}else if(state.type==='speed'){const v=state.results.pop();if(v){state.currentTarget=v.target;state.legStarted=Date.now();state.legEnds=Date.now()+speedModes[state.mode].leg*1000}}else if(state.type==='checkout'){const v=state.results.pop();if(v){if(state.mode==='random')state.currentTarget=v.target;if(state.mode==='crazy'){state.currentTarget=v.target;state.ready=true;state.changedAt=Date.now();state.nextChange=Date.now()+5000+Math.floor(Math.random()*10001)}}}state.canUndo=false;input='';err='';save();render()}
// --- Speed Game ---
const speedModes={easy:{max:60,leg:60},normal:{max:100,leg:45},pro:{max:180,leg:30},king:{max:150,leg:30}};
function speedModeName(m){return m==='easy'?'Easy':m==='normal'?'Normal':m==='pro'?'Pro':'King'}
function speedSetupView(){const m=speedModes[speedSetup];A.innerHTML=`<main class='app setup speed-setup'>${topBar('⚡ Speed Game')}<h1>${lang==='hr'?'Brzina pod pritiskom':'Speed under pressure'}</h1><label>${lang==='hr'?'TEŽINA':'DIFFICULTY'}</label><div class=choices>${['easy','normal','pro','king'].map(x=>`<button class='btn choice ${speedSetup===x?'selected':''}' data-speed-mode=${x}>${speedModeName(x)}</button>`).join('')}</div><div class=splitpreview>${speedSetup==='king'?'150 = DB · DB · DB':`1–${m.max} · ${m.leg}s ${lang==='hr'?'po meti':'per target'}`}</div><div class=maxnote>${lang==='hr'?'UKUPNO TRAJANJE: 5 MINUTA':'TOTAL DURATION: 5 MINUTES'}</div><button class='btn red start' data-a=startSpeed>GO</button></main>`}
function dartScores(){const a=[0,25,50];for(let n=1;n<=20;n++){a.push(n,n*2,n*3)}return [...new Set(a)]}
const reachable3=(()=>{const a=dartScores(),set=new Set();for(const x of a)for(const y of a)for(const z of a){const n=x+y+z;if(n>=1&&n<=180)set.add(n)}return [...set]})();
function randomSpeedTarget(mode){if(mode==='king')return 150;const max=speedModes[mode].max,pool=reachable3.filter(n=>n<=max);let n=pool[Math.floor(Math.random()*pool.length)];if(state?.currentTarget===n&&pool.length>1)n=pool[(pool.indexOf(n)+1+Math.floor(Math.random()*(pool.length-1)))%pool.length];return n}
function startSpeed(mode=speedSetup){clearInterval(speedClock);const now=Date.now();state={type:'speed',mode,currentTarget:null,results:[],started:now,totalEnds:now+300000,legStarted:now,legEnds:now+speedModes[mode].leg*1000,canUndo:false};state.currentTarget=randomSpeedTarget(mode);save();route='speedPlay';speedPlay()}
function speedRemaining(){return Math.max(0,state.totalEnds-Date.now())}
function speedLegRemaining(){return Math.max(0,state.legEnds-Date.now())}
function fmtClock(ms){const sec=Math.ceil(ms/1000),m=Math.floor(sec/60),s=sec%60;return `${m}:${String(s).padStart(2,'0')}`}
function speedPlay(){if(!state||state.type!=='speed')return;if(speedRemaining()<=0)return finishSpeed();clearInterval(speedClock);const total=fmtClock(speedRemaining()),leg=Math.ceil(speedLegRemaining()/1000),last=state.results.slice(-3);A.innerHTML=`<main class='app trainer-screen speed-game' data-game-surface><div class=top><div class=title>⚡ Speed · ${speedModeName(state.mode)}</div><div class=roundinfo>${total}</div></div><div class=targetlabel>${lang==='hr'?'META':'TARGET'}</div><div class='score targetscore'>${state.currentTarget}</div>${state.mode==='king'?`<div class='checkout-route'>DB · DB · DB</div>`:''}<div class='speed-leg-clock'><b>${leg}</b><small>${lang==='hr'?'SEKUNDI ZA METU':'SECONDS FOR TARGET'}</small></div><div class='challenge-actions'><button class='markbtn miss' data-speed-result=miss>${lang==='hr'?'PROMAŠAJ':'MISS'}</button><button class='markbtn hit' data-speed-result=hit>${lang==='hr'?'POGOĐENO':'HIT'}</button></div><div class=visits>${[0,1,2].map((_,i)=>`<div class=visit>${last[i]?`${last[i].target} · ${last[i].hit?'✓':last[i].timeout?'⌛':'×'}`:''}</div>`).join('')}</div><div class=maxnote>${lang==='hr'?'Ukupno 5:00 · istek vremena za metu = promašaj':'Total 5:00 · target timeout = miss'}</div><div class=gesturehint>••</div></main>`;speedClock=setInterval(speedTick,250)}
function speedTick(){if(!state||state.type!=='speed'){clearInterval(speedClock);return}if(speedRemaining()<=0){clearInterval(speedClock);finishSpeed();return}if(speedLegRemaining()<=0){submitSpeed(false,true);return}const info=document.querySelector('.speed-game .roundinfo'),lc=document.querySelector('.speed-leg-clock b');if(info)info.textContent=fmtClock(speedRemaining());if(lc)lc.textContent=Math.ceil(speedLegRemaining()/1000)}
function submitSpeed(hit,timeout=false){if(!state||state.type!=='speed')return;clearInterval(speedClock);const now=Date.now(),target=state.currentTarget;state.results.push({target,hit,timeout,ms:now-state.legStarted});state.canUndo=true;if(speedRemaining()<=0){save();return finishSpeed()}state.currentTarget=randomSpeedTarget(state.mode);state.legStarted=now;state.legEnds=now+speedModes[state.mode].leg*1000;save();speedPlay()}
function finishSpeed(){clearInterval(speedClock);if(!state||state.type!=='speed')return;const s=structuredClone(state),attempts=s.results.length,hits=s.results.filter(x=>x.hit).length,timeouts=s.results.filter(x=>x.timeout).length,hitTimes=s.results.filter(x=>x.hit).map(x=>x.ms),avg=hitTimes.length?hitTimes.reduce((a,b)=>a+b,0)/hitTimes.length/1000:0;let streak=0,best=0;for(const r of s.results){streak=r.hit?streak+1:0;best=Math.max(best,streak)}const all=loadObj('pb-speed-stats'),x=all[s.mode]||{games:0,attempts:0,hits:0,timeouts:0,bestStreak:0};x.games++;x.attempts+=attempts;x.hits+=hits;x.timeouts+=timeouts;x.bestStreak=Math.max(x.bestStreak,best);all[s.mode]=x;saveObj('pb-speed-stats',all);state=null;save();route='home';home();modal(`<h2>${lang==='hr'?'VRIJEME!':'TIME!'}</h2><div class=resultscore>${hits}/${attempts}</div><div class=statgrid><div><b>${attempts?Math.round(hits/attempts*100):0}%</b><small>${lang==='hr'?'POGODAKA':'HIT RATE'}</small></div><div><b>${attempts-hits}</b><small>${lang==='hr'?'PROMAŠAJA':'MISSES'}</small></div><div><b>${timeouts}</b><small>TIMEOUT</small></div><div><b>${best}</b><small>${lang==='hr'?'NAJBOLJI NIZ':'BEST STREAK'}</small></div><div><b>${avg.toFixed(1)}s</b><small>${lang==='hr'?'AVG POGODAK':'AVG HIT TIME'}</small></div><div><b>${attempts}</b><small>${lang==='hr'?'META':'TARGETS'}</small></div></div><div class=modalactions><button class='btn red' data-a=playSpeedAgain data-mode=${s.mode}>${t().playAgain}</button><button class='btn' data-a=home>${t().home}</button></div>`) }
function startGame(game=setup.game,out=setup.out){state={type:'x01',game:+game,out,maxRounds:limits[+game],left:+game,visits:[],canUndo:false,checkoutIntent:false,started:Date.now()};input='';err='';save();route='play';render()}
function startHigh(rounds=highSetup){state={type:'high',maxRounds:+rounds,visits:[],canUndo:false,started:Date.now()};input='';err='';save();route='highPlay';render()}
function startSplit(dir=splitSetup){state={type:'split',direction:dir,score:40,visits:[],canUndo:false,started:Date.now()};input='';err='';save();route='splitPlay';render()}
function startRtw(mode=rtwSetup.mode,bull=rtwSetup.bull){state={type:'rtw',mode,bull:bull===true||bull===1||bull==='1',visits:[],canUndo:false,started:Date.now()};save();route='rtwPlay';render()}
function startBobs(){state={type:'bobs',score:27,visits:[],canUndo:false,started:Date.now()};save();route='bobsPlay';render()}
function restartCurrent(){const s=state;document.querySelector('.modal')?.remove();if(s.type==='high')startHigh(s.maxRounds);else if(s.type==='split')startSplit(s.direction);else if(s.type==='rtw')startRtw(s.mode,s.bull);else if(s.type==='bobs')startBobs();else if(s.type==='checkout')startCheckout(s.mode,s.limitType,s.maxRounds||checkoutSetup.rounds,s.minutes||checkoutSetup.minutes,s.targets);else if(s.type==='challenge'){challengeSetup=s.mode||'2';startChallenge();}else if(s.type==='speed')startSpeed(s.mode);else startGame(s.game,s.out)}
function render(){if(route==='home')home();else if(route==='setup')setupView();else if(route==='highSetup')highSetupView();else if(route==='splitSetup')splitSetupView();else if(route==='highPlay')highPlay();else if(route==='splitPlay')splitPlay();else if(route==='rtwSetup')rtwSetupView();else if(route==='rtwPlay')rtwPlay();else if(route==='bobsPlay')bobsPlay();else if(route==='checkoutSetup')checkoutSetupView();else if(route==='checkoutPlay')checkoutPlay();else if(route==='challengeSetup')challengeSetupView();else if(route==='challengePlay')challengePlay();else if(route==='speedSetup')speedSetupView();else if(route==='speedPlay')speedPlay();else play()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.a;if(b.dataset.lang){lang=b.dataset.lang;localStorage.setItem('pb-lang',lang);render();return}if(a==='x01'){route='setup';render();return}if(a==='high'){route='highSetup';render();return}if(a==='split'){route='splitSetup';render();return}if(a==='rtw'){route='rtwSetup';render();return}if(a==='bobs'){startBobs();return}if(a==='checkout'){route='checkoutSetup';render();return}if(a==='challenge'){route='challengeSetup';render();return}if(a==='speed'){route='speedSetup';render();return}if(a==='startSpeed'){startSpeed();return}if(b.dataset.speedMode){speedSetup=b.dataset.speedMode;speedSetupView();return}if(b.dataset.speedResult){submitSpeed(b.dataset.speedResult==='hit',false);return}if(a==='startChallenge'){document.querySelector('.modal')?.remove();startChallenge();return}if(b.dataset.challengeMode){challengeSetup=b.dataset.challengeMode;challengeSetupView();return}if(a==='newChallengeRun'){newChallengeRun();return}if(a==='clearChallenge'){clearChallengeHistory();return}if(a==='confirmClearChallenge'){confirmClearChallenge();return}if(a==='home'){document.querySelector('.modal')?.remove();route='home';render();return}if(a==='resume'){route=routeForState();render();return}if(b.dataset.game&&!a){setup.game=+b.dataset.game;render();return}if(b.dataset.out&&!a){setup.out=b.dataset.out;render();return}if(b.dataset.highRounds){highSetup=+b.dataset.highRounds;render();return}if(b.dataset.splitDir){splitSetup=b.dataset.splitDir;render();return}if(b.dataset.rtwMode){rtwSetup.mode=b.dataset.rtwMode;render();return}if(b.dataset.rtwBull!==undefined){rtwSetup.bull=b.dataset.rtwBull==='1';render();return}if(b.dataset.checkoutMode){checkoutSetup.mode=b.dataset.checkoutMode;render();return}if(b.dataset.checkoutLimit){checkoutSetup.limitType=b.dataset.checkoutLimit;render();return}if(a==='start'){startGame();return}if(a==='startHigh'){startHigh();return}if(a==='startSplit'){startSplit();return}if(a==='startRtw'){startRtw();return}if(a==='startCheckout'){startCheckout();return}if(a==='checkoutIntent'){state.checkoutIntent=!state.checkoutIntent;save();play();return}if(b.dataset.key){const k=b.dataset.key;if(k==='OK'){const n=+(input||0);if(state.type==='high')submitHigh(n);else if(state.type==='split')submitSplit(n);else submitX01(n)}else{if(k==='⌫')input=input.slice(0,-1);else if(input.length<3)input+=k;render()}return}if(b.dataset.quick!==undefined){const n=+b.dataset.quick;if(state.type==='high')submitHigh(n);else submitX01(n);return}if(b.dataset.splitValue!==undefined){submitSplit(+b.dataset.splitValue,b.dataset.bullHits!==undefined?+b.dataset.bullHits:null);return}if(b.dataset.rtwHits!==undefined){submitRtw(+b.dataset.rtwHits);return}if(b.dataset.bobsHits!==undefined){submitBobs(+b.dataset.bobsHits);return}if(b.dataset.checkoutResult){submitCheckoutResult(b.dataset.checkoutResult==='hit');return}if(b.dataset.challengeResult){submitChallenge(b.dataset.challengeResult==='hit');return}if(b.dataset.attempts!==undefined){const v=state.visits.at(-1);if(v)v.checkoutAttempts=+b.dataset.attempts;save();document.querySelector('.modal')?.remove();play();return}if(b.dataset.finish){finishX01(+b.dataset.finish);return}if(a==='cancelFinish'){document.querySelector('.modal')?.remove();delete state.pendingScore;delete state.pendingBefore;delete state.pendingCheckoutVisit;state.canUndo=false;save();play();return}if(a==='undo'){undo();return}if(a==='closeMenu'){document.querySelector('.modal')?.remove();return}if(a==='undoMenu'){document.querySelector('.modal')?.remove();undo();return}if(a==='restart'){restartCurrent();return}if(a==='end'){endConfirm();return}if(a==='confirmEnd'){state=null;save();input='';err='';document.querySelector('.modal')?.remove();route='home';render();return}if(a==='playAgain'){document.querySelector('.modal')?.remove();startGame(+b.dataset.game,b.dataset.out);return}if(a==='playHighAgain'){document.querySelector('.modal')?.remove();startHigh(+b.dataset.rounds);return}if(a==='playSplitAgain'){document.querySelector('.modal')?.remove();startSplit(b.dataset.dir);return}if(a==='playRtwAgain'){document.querySelector('.modal')?.remove();startRtw(b.dataset.mode,b.dataset.bull);return}if(a==='playBobsAgain'){document.querySelector('.modal')?.remove();startBobs();return}if(a==='playSpeedAgain'){document.querySelector('.modal')?.remove();speedSetup=b.dataset.mode;startSpeed(b.dataset.mode);return}if(a==='playCheckoutAgain'){document.querySelector('.modal')?.remove();checkoutSetup.mode=b.dataset.mode;checkoutSetup.limitType=b.dataset.limit;checkoutSetup.rounds=+b.dataset.rounds;checkoutSetup.minutes=+b.dataset.minutes;startCheckout(b.dataset.mode,b.dataset.limit,+b.dataset.rounds,+b.dataset.minutes);return}});
